@Test
public final void test_isPolicyResourceUnique() throws Exception {
    // if store does not contain any matching policies then check should succeed
    RangerPolicyResourceSignature signature = mock(RangerPolicyResourceSignature.class);
    String hash = "hash-1";
    when(signature.getSignature()).thenReturn(hash);
    when(_factory.createPolicyResourceSignature(_policy)).thenReturn(signature);
    when(_policy.getService()).thenReturn("service-name");
    List<RangerPolicy> policies = null;
    when(_store.getPoliciesByResourceSignature("service-name", hash, true)).thenReturn(policies);
    policies = new ArrayList<RangerPolicy>();
    for (Action action : cu) {
        assertTrue(_validator.isPolicyResourceUnique(_policy, _failures, action));
        assertTrue(_validator.isPolicyResourceUnique(_policy, _failures, action));
    }
    /* 
		 * If store has a policy with matching signature then the check should fail with appropriate error message.
		 * - For create any match is a problem
		 * - Signature check can never fail for disabled policies! 
		 */
    RangerPolicy policy1 = mock(RangerPolicy.class);
    policies.add(policy1);
    when(_store.getPoliciesByResourceSignature("service-name", hash, true)).thenReturn(policies);
    // ensure policy is enabled
    when(_policy.getIsEnabled()).thenReturn(true);
    _failures.clear();
    assertFalse(_validator.isPolicyResourceUnique(_policy, _failures, Action.CREATE));
    _utils.checkFailureForSemanticError(_failures, "resources");
    // same check should pass if the policy is disabled
    when(_policy.getIsEnabled()).thenReturn(false);
    _failures.clear();
    assertTrue(_validator.isPolicyResourceUnique(_policy, _failures, Action.CREATE));
    assertTrue("failures collection wasn't empty!", _failures.isEmpty());
    // For Update match with itself is not a problem as long as it isn't itself, i.e. same id.
    // ensure policy is enabled
    when(_policy.getIsEnabled()).thenReturn(true);
    when(policy1.getId()).thenReturn(103L);
    when(_policy.getId()).thenReturn(103L);
    assertTrue(_validator.isPolicyResourceUnique(_policy, _failures, Action.UPDATE));
    // matching policy can't be some other policy (i.e. different id) because that implies a conflict.
    when(policy1.getId()).thenReturn(104L);
    assertFalse(_validator.isPolicyResourceUnique(_policy, _failures, Action.UPDATE));
    _utils.checkFailureForSemanticError(_failures, "resources");
    // same check should pass if the policy is disabled
    when(_policy.getIsEnabled()).thenReturn(false);
    _failures.clear();
    assertTrue(_validator.isPolicyResourceUnique(_policy, _failures, Action.UPDATE));
    assertTrue("failures collection wasn't empty!", _failures.isEmpty());
    // And validation should never pass if there are more than one policies with matching signature, regardless of their ID!!
    RangerPolicy policy2 = mock(RangerPolicy.class);
    // has same id as the policy being tested (_policy)
    when(policy2.getId()).thenReturn(103L);
    policies.add(policy2);
    // ensure policy is enabled
    when(_policy.getIsEnabled()).thenReturn(true);
    assertFalse(_validator.isPolicyResourceUnique(_policy, _failures, Action.UPDATE));
    _utils.checkFailureForSemanticError(_failures, "resources");
    // same check should pass if the policy is disabled
    when(_policy.getIsEnabled()).thenReturn(false);
    _failures.clear();
    assertTrue(_validator.isPolicyResourceUnique(_policy, _failures, Action.UPDATE));
    assertTrue("failures collection wasn't empty!", _failures.isEmpty());
}

@Test
public final void test_cacheBehavior() {
    // wipe the cache clean
    RangerServiceDefHelper._Cache.clear();
    // let's add one entry to the cache
    Delegate delegate = mock(Delegate.class);
    Date aDate = getNow();
    String serviceName = "a-service-def";
    when(delegate.getServiceFreshnessDate()).thenReturn(aDate);
    when(delegate.getServiceName()).thenReturn(serviceName);
    RangerServiceDefHelper._Cache.put(serviceName, delegate);
    // create a service def with matching date value
    _serviceDef = mock(RangerServiceDef.class);
    when(_serviceDef.getName()).thenReturn(serviceName);
    when(_serviceDef.getUpdateTime()).thenReturn(aDate);
    // since cache has it, we should get back the one that we have added
    _helper = new RangerServiceDefHelper(_serviceDef);
    assertTrue("Didn't get back the same object that was put in cache", delegate == _helper._delegate);
    // if we change the date then that should force helper to create a new delegate instance
    /*
		 * NOTE:: current logic would replace the cache instance even if the one in the cache is newer.  This is not likely to happen but it is important to call this out
		 * as in rare cases one may end up creating re creating delegate if threads have stale copies of service def.
		 */
    when(_serviceDef.getUpdateTime()).thenReturn(getLastMonth());
    _helper = new RangerServiceDefHelper(_serviceDef);
    assertTrue("Didn't get a delegate different than what was put in the cache", delegate != _helper._delegate);
    // now that a new instance was added to the cache let's ensure that it got added to the cache
    Delegate newDelegate = _helper._delegate;
    _helper = new RangerServiceDefHelper(_serviceDef);
    assertTrue("Didn't get a delegate different than what was put in the cache", newDelegate == _helper._delegate);
}

